package com.lims.controller;
import com.lims.model.*;import com.lims.service.*;import jakarta.servlet.ServletException;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import java.math.BigDecimal;import java.util.*;
@WebServlet(name="ManagerCatalogServlet",urlPatterns="/app/manager/catalog")
public class ManagerCatalogServlet extends BaseServlet{
 private final ManagerService auth=new ManagerService();private final ManagerCatalogService service=new ManagerCatalogService();
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=getCurrentUser(req);if(u==null||!auth.isActiveManager(u.getUserId())){resp.sendError(403,"Manager role required");return;}String tab=req.getParameter("tab");if(!List.of("products","brands","lines","suppliers","customers").contains(tab))tab="products";req.setAttribute("user",u);req.setAttribute("activeManagerMenu","catalog");req.setAttribute("catalogTab",tab);req.setAttribute("notice",req.getParameter("notice"));req.setAttribute("error",req.getParameter("error"));req.setAttribute("brands",service.brands());req.setAttribute("lines",service.lines());req.setAttribute("products",service.products());req.setAttribute("suppliers",service.suppliers());req.setAttribute("customers",service.customers());int edit=parseId(req.getParameter("edit"));if(edit>0){switch(tab){case "products":req.setAttribute("editProduct",service.product(edit));break;case "brands":req.setAttribute("editBrand",service.brands().stream().filter(x->x.getBrandId()==edit).findFirst().orElse(null));break;case "lines":req.setAttribute("editLine",service.lines().stream().filter(x->x.getProductLineId()==edit).findFirst().orElse(null));break;case "suppliers":req.setAttribute("editSupplier",service.supplier(edit));break;case "customers":req.setAttribute("editCustomer",service.customer(edit));break;}}forward(req,resp,"manager-catalog.jsp");}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{req.setCharacterEncoding("UTF-8");User u=getCurrentUser(req);if(u==null||!auth.isActiveManager(u.getUserId())){resp.sendError(403,"Manager role required");return;}String tab=req.getParameter("tab");if(tab==null)tab="products";String a=req.getParameter("action");try{switch(a==null?"":a){case "saveBrand":service.saveBrand(u,req.getParameter("brandId"),req.getParameter("brandName"),req.getParameter("status"),getClientIP(req),req.getHeader("User-Agent"));break;case "deleteBrand":service.deleteBrand(u,req.getParameter("brandId"),getClientIP(req),req.getHeader("User-Agent"));break;case "saveLine":service.saveLine(u,req.getParameter("lineId"),req.getParameter("brandId"),req.getParameter("lineName"),req.getParameter("status"),getClientIP(req),req.getHeader("User-Agent"));break;case "setLineStatus":service.setLineStatus(u,req.getParameter("lineId"),req.getParameter("status"),getClientIP(req),req.getHeader("User-Agent"));break;case "saveProduct":service.saveProduct(u,readProduct(req),getClientIP(req),req.getHeader("User-Agent"));break;case "deactivateProduct":service.deactivateProduct(u,req.getParameter("productId"),getClientIP(req),req.getHeader("User-Agent"));break;case "saveSupplier":service.saveSupplier(u,readSupplier(req),getClientIP(req),req.getHeader("User-Agent"));break;case "saveCustomer":service.saveCustomer(u,readCustomer(req),getClientIP(req),req.getHeader("User-Agent"));break;case "deactivateCustomer":service.deactivateCustomer(u,req.getParameter("customerId"),getClientIP(req),req.getHeader("User-Agent"));break;default:throw new IllegalArgumentException("Thao tác danh mục không hợp lệ.");}redirectBack(req,resp,tab,"notice","Đã lưu thay đổi danh mục.");}catch(IllegalArgumentException|IllegalStateException e){redirectBack(req,resp,tab,"error",e.getMessage());}}
 private Product readProduct(HttpServletRequest r){Product p=new Product();p.setProductId(parseFormId(r.getParameter("productId")));p.setProductCode(r.getParameter("productCode"));p.setProductName(r.getParameter("productName"));p.setProductLineId(parseId(r.getParameter("productLineId")));p.setCpu(r.getParameter("cpu"));p.setRam(r.getParameter("ram"));p.setStorage(r.getParameter("storage"));p.setGpu(r.getParameter("gpu"));p.setScreen(r.getParameter("screen"));p.setStatus(r.getParameter("status"));try{p.setUnitPrice(new BigDecimal(r.getParameter("unitPrice")));}catch(Exception ignored){}return p;}
 private Supplier readSupplier(HttpServletRequest r){Supplier x=new Supplier();x.setSupplierId(parseFormId(r.getParameter("supplierId")));x.setSupplierName(r.getParameter("supplierName"));x.setContactName(r.getParameter("contactName"));x.setEmail(r.getParameter("email"));x.setPhone(r.getParameter("phone"));x.setAddress(r.getParameter("address"));x.setStatus(r.getParameter("status"));return x;}
 private Customer readCustomer(HttpServletRequest r){Customer x=new Customer();x.setCustomerId(parseFormId(r.getParameter("customerId")));x.setCustomerName(r.getParameter("customerName"));x.setPhone(r.getParameter("phone"));x.setEmail(r.getParameter("email"));x.setAddress(r.getParameter("address"));x.setStatus(r.getParameter("status"));return x;}
 private int parseId(String x){try{return Integer.parseInt(x);}catch(Exception e){return -1;}}private int parseFormId(String x){if(x==null||x.isBlank())return 0;try{return Math.max(0,Integer.parseInt(x));}catch(Exception e){return 0;}}private void redirectBack(HttpServletRequest r,HttpServletResponse s,String tab,String key,String value)throws IOException{redirect(r,s,"/app/manager/catalog?tab="+URLEncoder.encode(tab,StandardCharsets.UTF_8)+"&"+key+"="+URLEncoder.encode(value,StandardCharsets.UTF_8));}
}
